import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/EN.P9aPnFBv.js";import{_ as t}from"./chunks/DIS.DdpTdGGD.js";import{_ as i,a as n}from"./chunks/M-BT-BK.DTMS2NtJ.js";import{_ as a}from"./chunks/BDM.scaBLLhv.js";import{_ as r,o as l,c as d,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const k=JSON.parse('{"title":"Libre bridge","description":"","frontmatter":{},"headers":[],"relativePath":"install/libreBT.md","filePath":"install/libreBT.md"}'),c={name:"install/libreBT.md"};function m(u,s,h,g,b,y){return l(),d("div",null,[...s[0]||(s[0]=[p('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Libre Bluetooth</p></div><p>Many NFC to Bluetooth bridges are available on the market for Libre sensors.</p><p>The original project was developed by Joern: <a href="https://github.com/JoernL/LimiTTer" target="_blank" rel="noreferrer">LimiTTer</a>. You need to remember this name as it will appear as the default bridge name when the actual device is not identified. Unless you actually have a LimiTTer (or directly connect a Libre 2), seeing this name means your bridge is not connected to xDrip.</p><p>xDrip supports some of them for some sensors.<br><strong>Libre H, Libre 2/2+ US/CA/AUS are not supported.</strong><br> You can use Diabox or Juggluco in <a href="./libre2patch.html">Libre patched app</a> mode.</p><p>Here below is a compatibility table for supported bridge devices; for compatible sensors, the <strong>minimum</strong> firmware version is indicated.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Bridge</th><th style="text-align:center;">- Libre 1 / Pro -</th><th style="text-align:center;">- 14 days US -</th><th style="text-align:center;">- Libre 2/2+ EU -</th></tr></thead><tbody><tr><td style="text-align:center;">MiaoMiao</td><td style="text-align:center;"><code>Yes</code></td><td style="text-align:center;"><code>39*</code></td><td style="text-align:center;"><code>39*</code></td></tr><tr><td style="text-align:center;">MiaoMiao 2</td><td style="text-align:center;"><code>Yes</code></td><td style="text-align:center;"><code>7*</code></td><td style="text-align:center;"><code>7*</code></td></tr><tr><td style="text-align:center;">MiaoMiao 3</td><td style="text-align:center;"><code>Yes</code></td><td style="text-align:center;"><code>3A*</code></td><td style="text-align:center;"><code>3A*</code></td></tr><tr><td style="text-align:center;">Atom</td><td style="text-align:center;"><code>Yes</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p><em>Note:</em><br><em><code>*</code> <a href="./../use/OOP.html">external OOP add-on required</a></em></p><br><h2 id="bridge-settings" tabindex="-1">Bridge settings <a class="header-anchor" href="#bridge-settings" aria-label="Permalink to &quot;Bridge settings&quot;">​</a></h2><p>If you haven&#39;t yet, <a href="./install.html#make-sure-xdrip-will-not-be-put-to-sleep">check xDrip will not be put to sleep</a>.</p><p>Before trying to connect your bridge, verify your settings are correct to avoid frequent disconnections.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  Less Common Settings<br>   Bluetooth Settings</p></div><p>Use settings as shown below to start with.</p><p>Bluetooth must be on. <strong>Enable</strong> <code>Turn Bluetooth on</code>.</p><div class="admonition xdripitem"><p class="admonition-title">Turn Bluetooth on <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Automatically enable Bluetooth if it is switched off when we try to connect to a Bluetooth device</p></div><p><strong>Enable</strong> the Watchdog but read the info below.</p><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Watchdog <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Reset Bluetooth by turning it off and on if we don&#39;t get anything in 20 minutes</p></div><div class="info custom-block"><p class="custom-block-title">Info</p><p>Mind the Bluetooth watchdog will turn your phone Bluetooth off, then on: this will lead to a temporary Bluetooth disconnection on all connected devices. You might want to disable this feature if you use AAPS and your bridge/pump doesn&#39;t automatically recover the Bluetooth connection.</p></div><p><strong>Disable</strong> close GATT.</p><div class="admonition xdripitem"><p class="admonition-title">Close GATT on BLE disconnect <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> If the Bluetooth watchdog activates often then you can try unchecking this option to see if it helps</p></div><p>If your bridge loses connection and scanning Bluetooth allows you to recover, you can try to enable <code>Use scanning</code>. Leave <strong>disabled</strong> to start.</p><div class="admonition xdripitem"><p class="admonition-title">Use scanning <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Scan before connecting on xBridge and Libre Bluetooth</p></div><p>For Samsung and many Chinese phones you <strong>must disable <code>Trust Auto-Connect</code></strong>! If your phone loses connection you should <strong>disable</strong> it.</p><div class="admonition xdripitem"><p class="admonition-title">Trust Auto-Connect <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Use and trust Android Bluetooth auto connect feature</p></div><p>For Android version 8 and above you can enable <code>Use Background Scans</code>. If you lose connection, <strong>leave it disabled</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Use Background Scans <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Use Android 8+ background scanning feature</p></div><p>Leave both the options below <strong>disabled</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Wakelocks <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Older Bluetooth wakelocks which can drain extra battery but might be needed for Bluetooth reception</p></div><div class="admonition xdripitem"><p class="admonition-title">Constantly reset Bluetooth <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Reset Bluetooth by turning it off and on every few minutes! Only select if you are testing. It may disrupt anything else using Bluetooth.</p></div><p>If your bridge is a Transmitter_T or a Droplet, enable this; otherwise keep it <strong>disabled</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Transmitter (PL) support <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Experimental support for &#39;Transmitter&#39; device from @FPV-UAV - test only</p></div><p>If you have connection losses you can <strong>enable</strong> polling mode. It will not do anything useful but keep the phone Bluetooth awake.</p><div class="admonition xdripitem"><p class="admonition-title">xBridge+ Polling Mode <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Experimental support for xBridge+ polling feature.</p></div><p>If your bridge is an old compatible BluCon you can enable this; if you have multiple daily pairing requests, keep it <strong>disabled</strong>.<br><em>Note: only BluCon bonds to Android, other bridges don&#39;t.</em></p><div class="admonition xdripitem"><p class="admonition-title">Allow BluCon unbonding <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Only suitable for phones which support automatic pairing.</p></div><br><p>Restart your phone to make sure all parameters are being taken into account.</p><br><h2 id="connect-bluetooth-bridge" tabindex="-1">Connect Bluetooth bridge <a class="header-anchor" href="#connect-bluetooth-bridge" aria-label="Permalink to &quot;Connect Bluetooth bridge&quot;">​</a></h2><p>Make sure your bridge is not connected to anything else: any other device and any other app.<br> Scan Bluetooth.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Bluetooth Scan</p></div><p>If scan doesn&#39;t start automatically, select <code>SCAN</code>.</p><img src="'+i+'" style="zoom:75%;"><p>If your bridge doesn&#39;t show up, make sure it&#39;s fully charged (or has a new battery) and reset it.</p><p>Once visible, select it.</p><p>If your bridge is a Blucon, enter the code written on the side.</p><img src="'+n+'" style="zoom:55%;"><p>Position it correctly on your sensor. Some bridges have very little tolerance with respect to angle and distance to the sensor.</p><div class="info custom-block"><p class="custom-block-title">External Add-on</p><p>If your sensor requires an <a href="./../use/OOP.html">out of process algorithm</a>, make sure it is installed now.</p></div><br><p>Continue to <a href="./../use/startsensor.html#libre">Start Sensor</a></p><h2 id="stop-libre-sensor" tabindex="-1">Stop Libre sensor <a class="header-anchor" href="#stop-libre-sensor" aria-label="Permalink to &quot;Stop Libre sensor&quot;">​</a></h2><p>xDrip cannot physically stop a Libre sensor; it will stop running by itself after 14 days and 12 hours and keep showing the last value.</p><p>Still, when changing sensor it is strongly recommended to inform xDrip of the change by stopping the sensor.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Stop Sensor</p></div><p>Confirm you really want to stop the sensor.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"> Stop Sensor <span class="symbol"></span></p><p> Only stop your sensor when you actually plan to remove it, otherwise leave it running!</p><p>       <span style="background-color:white;color:black;"> STOP SENSOR </span></p></div><p>This will reset all calibrations and allow xDrip to start a new sensor.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',60)])])}const S=r(c,[["render",m]]);export{k as __pageData,S as default};
